    def func(x):
        return x
    wrapper = method_wrapper(func)
    assert wrapper.__func__ is func, ('assertIs', wrapper.__func__, func)
    assert wrapper.__wrapped__ is func, ('assertIs', wrapper.__wrapped__, func)
