    def callnum(num):
        """Decorator factory that returns a decorator that replaces the
            passed-in function with one that returns the value of 'num'"""

        def deco(func):
            return lambda: num
        return deco

    @callnum(2)
    @callnum(1)
    def foo():
        return 42
    assert foo() == 2, ('assertEqual', foo(), 2)
