def _t():

    class _SelfNS:
        pass
    self = _SelfNS()
    actions = []

    def make_decorator(tag):
        actions.append('makedec' + tag)

        def decorate(func):
            actions.append('calldec' + tag)
            return func
        return decorate

    class NameLookupTracer(object):

        def __init__(self, index):
            self.index = index

        def __getattr__(self, fname):
            if fname == 'make_decorator':
                opname, res = ('evalname', make_decorator)
            elif fname == 'arg':
                opname, res = ('evalargs', str(self.index))
            else:
                assert False, 'Unknown attrname %s' % fname
            actions.append('%s%d' % (opname, self.index))
            return res
    c1, c2, c3 = map(NameLookupTracer, [1, 2, 3])
    expected_actions = ['evalname1', 'evalargs1', 'makedec1', 'evalname2', 'evalargs2', 'makedec2', 'evalname3', 'evalargs3', 'makedec3', 'calldec3', 'calldec2', 'calldec1']
    actions = []

    @c1.make_decorator(c1.arg)
    @c2.make_decorator(c2.arg)
    @c3.make_decorator(c3.arg)
    def foo():
        return 42
    assert foo() == 42, ('assertEqual', foo(), 42)
    assert actions == expected_actions, ('assertEqual', actions, expected_actions)
    actions = []

    def bar():
        return 42
    bar = c1.make_decorator(c1.arg)(c2.make_decorator(c2.arg)(c3.make_decorator(c3.arg)(bar)))
    assert bar() == 42, ('assertEqual', bar(), 42)
    assert actions == expected_actions, ('assertEqual', actions, expected_actions)
